1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * Rejects a create-owner request that is missing or blank in any required field, before
15	 * {@link BuildOwner} runs. Each offending field name is collected and reported together as a
16	 * 400 whose {@code errors} array lists them (see {@link MissingOwnerFieldsException}).
17	 *
18	 * <p>Also normalizes the telephone: every non-digit character is stripped, and the result must
19	 * be exactly 10 digits or the request is rejected with a 400 (see
20	 * {@link InvalidTelephoneException}). The normalized 10-digit value is stored back on the
21	 * request so it is persisted and returned as {@code telephone}.
22	 *
23	 * <p>Binds the request body for the pipeline and republishes it as a variable so that
24	 * {@link BuildOwner} can read it without a second {@code @RequestBody} binding.
25	 */
26	public class ValidateOwnerFields {
27	
28	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
29	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
30	        List<String> missing = new ArrayList<>();
31	        require(missing, "firstName", request.getFirstName());
32	        require(missing, "lastName", request.getLastName());
33	        require(missing, "address", request.getAddress());
34	        require(missing, "city", request.getCity());
35	        require(missing, "telephone", request.getTelephone());
36	        if (!missing.isEmpty()) {
37	            throw new MissingOwnerFieldsException(missing);
38	        }
39	        String digits = request.getTelephone().replaceAll("\\D", "");
40	        if (digits.length() != 10) {
41	            throw new InvalidTelephoneException(request.getTelephone());
42	        }
43	        request.setTelephone(digits);
44	        OwnerEmail.normalize(request);
45	        validated.set(request);
46	    }
47	
48	    private static void require(List<String> missing, String field, String value) {
49	        if (value == null || value.isBlank()) {
50	            missing.add(field);
51	        }
52	    }
53	}
