3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create-owner request whose normalized telephone is already used by any other owner.
11	 * Runs after {@link ValidateOwnerFields} (which strips non-digit characters and republishes the
12	 * request as a variable) and before {@link BuildOwner}. Every existing owner's telephone is
13	 * normalized the same way before comparison, and a match is reported as a 409 (see
14	 * {@link DuplicateTelephoneException}).
15	 */
16	public class CheckUniqueTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        String telephone = normalize(request.getTelephone());
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(normalize(existing.getTelephone()))) {
23	                throw new DuplicateTelephoneException(request.getTelephone());
24	            }
25	        }
26	    }
27	
28	    private static String normalize(String telephone) {
29	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
30	    }
31	}
