1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Shared email handling for the owner create/update pipelines. Email is optional; when a
11	 * request carries one it must be a syntactically valid address, and it is stored and
12	 * returned lower-cased.
13	 */
14	final class OwnerEmail {
15	
16	    /**
17	     * A pragmatic address check: a non-empty local part, an {@code @}, then a domain with at
18	     * least one dot and no whitespace. Rejects values like {@code not-an-email} (no {@code @}).
19	     */
20	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
21	
22	    private OwnerEmail() {
23	    }
24	
25	    /**
26	     * Validates and normalizes the email on the request in place. Absent (null) email is left
27	     * untouched; a present value is trimmed, validated and lower-cased.
28	     *
29	     * @throws InvalidEmailException when an email is present but not a valid address.
30	     */
31	    static void normalize(OwnerFieldsDto request) throws InvalidEmailException {
32	        String email = request.getEmail();
33	        if (email == null) {
34	            return;
35	        }
36	        String trimmed = email.trim();
37	        if (!EMAIL.matcher(trimmed).matches()) {
38	            throw new InvalidEmailException(email);
39	        }
40	        request.setEmail(trimmed.toLowerCase(Locale.ROOT));
41	    }
42	}
